import { FolderPlus, Plus, X } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { useI18n, useOptionalI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { Button, IconButton } from '../button';
import { SimpleSelect } from '../select';
import { Toggle, ToggleGroup } from '../toggle-group';
import {
  createQueryCondition,
  createQueryGroup,
  operatorArity,
  operatorsFor,
  queryToString,
  type QueryCondition,
  type QueryField,
  type QueryGroup,
  type QueryNode,
  type QueryOperator,
  type QueryValue,
} from './query';
import { queryBuilderVariants } from './query-builder.variants';
import { QueryValueEditor } from './QueryValueEditor';

export interface QueryBuilderProps {
  /** Fields a condition can test. */
  fields: QueryField[];
  /** The query tree (controlled). The root is a group. */
  value?: QueryGroup;
  defaultValue?: QueryGroup;
  onChange?: (value: QueryGroup) => void;
  /** Group nesting limit, counting the root (1 = no sub-groups). */
  maxDepth?: number;
  /** Show the query as text under the builder (`queryToString`). */
  showPreview?: boolean;
  /** Locale for dates and the preview. Defaults to the I18nProvider's. */
  locale?: string;
  disabled?: boolean;
  className?: string;
  'aria-label'?: string;
}

const EMPTY_ROOT: QueryGroup = { type: 'group', id: 'root', combinator: 'and', children: [] };

function mapNode(node: QueryNode, id: string, fn: (n: QueryNode) => QueryNode | null): QueryNode | null {
  if (node.id === id) return fn(node);
  if (node.type === 'condition') return node;
  const children = node.children.map((c) => mapNode(c, id, fn)).filter((c): c is QueryNode => c !== null);
  return { ...node, children };
}

/**
 * Visual query editor: nested AND/OR groups of field / operator / value conditions. Fields are
 * typed (text, number, enum, date, boolean) and each type offers its operators and value editor.
 * The value is a serialisable tree; `queryToString` and `evaluateQuery` read it.
 */
export function QueryBuilder({
  fields,
  value,
  defaultValue,
  onChange,
  maxDepth = 3,
  showPreview = false,
  locale: localeProp,
  disabled,
  className,
  'aria-label': ariaLabel,
}: QueryBuilderProps) {
  const { t } = useI18n();
  const providerLocale = useOptionalI18n()?.locale;
  const locale = localeProp ?? providerLocale;
  const [inner, setInner] = useState<QueryGroup>(defaultValue ?? EMPTY_ROOT);
  const tree = value ?? inner;
  const rootRef = useRef<HTMLDivElement | null>(null);
  const pendingFocus = useRef<string | null>(null);
  const s = queryBuilderVariants();

  useEffect(() => {
    if (!pendingFocus.current) return;
    const el = rootRef.current?.querySelector<HTMLElement>(pendingFocus.current);
    pendingFocus.current = null;
    el?.focus();
  });

  const commit = (next: QueryGroup) => {
    setInner(next);
    onChange?.(next);
  };
  const update = (id: string, fn: (n: QueryNode) => QueryNode | null) => {
    const next = mapNode(tree, id, fn);
    if (next && next.type === 'group') commit(next);
  };
  const patchCondition = (id: string, patch: Partial<QueryCondition>) =>
    update(id, (n) => (n.type === 'condition' ? { ...n, ...patch } : n));

  const addTo = (group: QueryGroup, node: QueryNode) => {
    pendingFocus.current = node.type === 'condition' ? `[data-query-node="${node.id}"] [role="combobox"]` : `[data-query-node="${node.id}"] [data-query-part="add-condition"]`;
    update(group.id, (n) => (n.type === 'group' ? { ...n, children: [...n.children, node] } : n));
  };
  const remove = (parent: QueryGroup, id: string) => {
    pendingFocus.current = `[data-query-node="${parent.id}"] [data-query-part="add-condition"]`;
    update(id, () => null);
  };

  const renderCondition = (c: QueryCondition, index: number, parent: QueryGroup) => {
    const field = fields.find((f) => f.id === c.field);
    const operators = operatorsFor(field);
    return (
      <div role="group" aria-label={t('queryBuilder.condition', { index })} data-query-node={c.id} className={s.condition()}>
        <SimpleSelect
          aria-label={t('queryBuilder.field')}
          items={fields.map((f) => ({ value: f.id, label: f.label }))}
          value={c.field || null}
          onValueChange={(id) => {
            const nextField = fields.find((f) => f.id === id);
            if (nextField) patchCondition(c.id, { field: nextField.id, operator: operatorsFor(nextField)[0] ?? 'eq', value: undefined });
          }}
          disabled={disabled}
          size="sm"
          className={s.fieldSelect()}
        />
        <SimpleSelect<QueryOperator>
          aria-label={t('queryBuilder.operator')}
          items={operators.map((op) => ({ value: op, label: t(`queryBuilder.op.${op}`) }))}
          value={c.operator}
          onValueChange={(op) => {
            if (!op) return;
            const keep = operatorArity(op) === operatorArity(c.operator);
            patchCondition(c.id, { operator: op, value: keep ? c.value : undefined });
          }}
          disabled={disabled || !field}
          size="sm"
          className={s.operatorSelect()}
        />
        <div className={s.value()}>
          <QueryValueEditor condition={c} field={field} onChange={(v: QueryValue | undefined) => patchCondition(c.id, { value: v })} disabled={disabled} locale={locale} />
        </div>
        <IconButton
          icon={X}
          label={t('queryBuilder.removeCondition', { index })}
          size="sm"
          onClick={() => remove(parent, c.id)}
          disabled={disabled}
        />
      </div>
    );
  };

  const renderGroup = (group: QueryGroup, depth: number, parent: QueryGroup | null) => {
    const isRoot = parent === null;
    const joiner = t(group.combinator === 'and' ? 'queryBuilder.and' : 'queryBuilder.or');
    return (
      <div
        role="group"
        aria-label={isRoot ? (ariaLabel ?? t('queryBuilder.label')) : t('queryBuilder.group')}
        data-query-node={group.id}
        className={queryBuilderVariants({ depth: Math.min(depth, 2) as 0 | 1 | 2 }).group()}
      >
        <div className={s.groupHeader()}>
          <ToggleGroup
            aria-label={t('queryBuilder.combinator')}
            size="sm"
            value={[group.combinator]}
            onValueChange={(v) => {
              const combinator = v[0];
              if (combinator === 'and' || combinator === 'or') update(group.id, (n) => (n.type === 'group' ? { ...n, combinator } : n));
            }}
            disabled={disabled}
          >
            <Toggle value="and">{t('queryBuilder.and')}</Toggle>
            <Toggle value="or">{t('queryBuilder.or')}</Toggle>
          </ToggleGroup>
          {!isRoot && <IconButton icon={X} label={t('queryBuilder.removeGroup')} size="sm" onClick={() => remove(parent, group.id)} disabled={disabled} />}
        </div>
        {group.children.length > 0 ? (
          <div className={s.list()}>
            {group.children.map((child, i) => (
              <div key={child.id} className={s.item()}>
                <span aria-hidden className={s.joiner()}>
                  {i === 0 ? '' : joiner}
                </span>
                {child.type === 'condition' ? renderCondition(child, i + 1, group) : renderGroup(child, depth + 1, group)}
              </div>
            ))}
          </div>
        ) : (
          isRoot && <p className={s.empty()}>{t('queryBuilder.empty')}</p>
        )}
        <div className={s.footer()}>
          <Button variant="secondary" size="sm" icon={Plus} onClick={() => addTo(group, createQueryCondition(fields[0]))} disabled={disabled} data-query-part="add-condition">
            {t('queryBuilder.addCondition')}
          </Button>
          {depth + 1 < maxDepth && (
            <Button variant="ghost" size="sm" icon={FolderPlus} onClick={() => addTo(group, createQueryGroup('and', [createQueryCondition(fields[0])]))} disabled={disabled}>
              {t('queryBuilder.addGroup')}
            </Button>
          )}
        </div>
      </div>
    );
  };

  const preview = showPreview ? queryToString(tree, { fields, t }) : '';
  return (
    <div ref={rootRef} className={cn(s.root(), className)}>
      {renderGroup(tree, 0, null)}
      {showPreview && preview && (
        <output aria-live="polite" className={s.preview()}>
          {preview}
        </output>
      )}
    </div>
  );
}

import { useI18n } from '../../i18n/I18nProvider';
import { toISODate } from '../calendar/calendar-utils';
import { DatePicker } from '../date-picker';
import { Input } from '../input';
import { MultiSelect } from '../multi-select';
import { NumberInput } from '../number-input';
import { SimpleSelect } from '../select';
import { operatorArity, type QueryCondition, type QueryField, type QueryValue } from './query';
import { queryBuilderVariants } from './query-builder.variants';

export interface QueryValueEditorProps {
  condition: QueryCondition;
  field: QueryField | undefined;
  onChange: (value: QueryValue | undefined) => void;
  disabled?: boolean;
  locale?: string;
}

const s = queryBuilderVariants();

const fromISO = (v: unknown): Date | null => {
  if (typeof v !== 'string') return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v);
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
};
const asNumber = (v: unknown): number | null => (typeof v === 'number' && !Number.isNaN(v) ? v : null);

/** The value control for a condition: depends on the field type and the operator's arity. */
export function QueryValueEditor({ condition, field, onChange, disabled, locale }: QueryValueEditorProps) {
  const { t } = useI18n();
  const arity = operatorArity(condition.operator);
  if (!field || arity === 'none') return null;
  const v = condition.value;
  const pair = Array.isArray(v) && arity === 'pair' ? v : [null, null];

  if (field.type === 'enum') {
    const options = field.options ?? [];
    if (arity === 'list') {
      return (
        <MultiSelect
          aria-label={t('queryBuilder.value')}
          options={options}
          value={Array.isArray(v) ? (v as unknown[]).map(String) : []}
          onValueChange={(vals) => onChange(vals)}
          disabled={disabled}
          size="sm"
          className={s.valueControl()}
        />
      );
    }
    return (
      <SimpleSelect
        aria-label={t('queryBuilder.value')}
        items={options}
        value={typeof v === 'string' ? v : null}
        onValueChange={(val) => onChange(val ?? undefined)}
        disabled={disabled}
        size="sm"
        className={s.valueControl()}
      />
    );
  }

  if (field.type === 'number') {
    if (arity === 'pair') {
      const set = (i: 0 | 1, n: number | null) => {
        const next: [number | null, number | null] = [asNumber(pair[0]), asNumber(pair[1])];
        next[i] = n;
        onChange(next[0] === null && next[1] === null ? undefined : next);
      };
      return (
        <>
          <NumberInput aria-label={t('queryBuilder.valueFrom')} value={asNumber(pair[0])} onValueChange={(n) => set(0, n)} disabled={disabled} size="sm" hideSteppers className="w-28" />
          <NumberInput aria-label={t('queryBuilder.valueTo')} value={asNumber(pair[1])} onValueChange={(n) => set(1, n)} disabled={disabled} size="sm" hideSteppers className="w-28" />
        </>
      );
    }
    return (
      <NumberInput
        aria-label={t('queryBuilder.value')}
        value={asNumber(v)}
        onValueChange={(n) => onChange(n ?? undefined)}
        disabled={disabled}
        size="sm"
        hideSteppers
        className="w-36"
      />
    );
  }

  if (field.type === 'date') {
    if (arity === 'pair') {
      const set = (i: 0 | 1, d: Date | null) => {
        const next: [string, string] = [typeof pair[0] === 'string' ? pair[0] : '', typeof pair[1] === 'string' ? pair[1] : ''];
        next[i] = d ? toISODate(d) : '';
        onChange(next[0] || next[1] ? next : undefined);
      };
      return (
        <>
          <DatePicker aria-label={t('queryBuilder.valueFrom')} value={fromISO(pair[0])} onValueChange={(d) => set(0, d)} locale={locale} disabled={disabled} size="sm" className="w-44" />
          <DatePicker aria-label={t('queryBuilder.valueTo')} value={fromISO(pair[1])} onValueChange={(d) => set(1, d)} locale={locale} disabled={disabled} size="sm" className="w-44" />
        </>
      );
    }
    return (
      <DatePicker
        aria-label={t('queryBuilder.value')}
        value={fromISO(v)}
        onValueChange={(d) => onChange(d ? toISODate(d) : undefined)}
        locale={locale}
        disabled={disabled}
        size="sm"
        className="w-44"
      />
    );
  }

  return (
    <Input
      aria-label={t('queryBuilder.value')}
      value={typeof v === 'string' ? v : v === undefined || v === null ? '' : String(v)}
      onChange={(e) => onChange(e.currentTarget.value === '' ? undefined : e.currentTarget.value)}
      disabled={disabled}
      size="sm"
      className={s.valueControl()}
    />
  );
}

export { QueryBuilder, type QueryBuilderProps } from './QueryBuilder';
export { QueryValueEditor, type QueryValueEditorProps } from './QueryValueEditor';
export {
  QUERY_OPERATORS,
  operatorsFor,
  operatorArity,
  createQueryGroup,
  createQueryCondition,
  isConditionComplete,
  queryToString,
  evaluateQuery,
  type QueryFieldType,
  type QueryOperator,
  type QueryField,
  type QueryFieldOption,
  type QueryValue,
  type QueryCondition,
  type QueryGroup,
  type QueryNode,
  type QueryToStringOptions,
} from './query';
export { queryBuilderVariants, type QueryBuilderVariantProps } from './query-builder.variants';
export { doc as queryBuilderDoc } from './QueryBuilder.doc';

import { tv, type VariantProps } from '../../utils/tv';

/**
 * Nested groups as bordered cards (each level one step deeper in tone), a combinator switch per
 * group, and condition rows that wrap on narrow screens.
 */
export const queryBuilderVariants = tv({
  slots: {
    root: 'flex w-full min-w-0 flex-col gap-3',
    group: 'flex min-w-0 flex-col gap-2.5 rounded-lg border border-border p-3',
    groupHeader: 'flex flex-wrap items-center justify-between gap-2',
    list: 'flex min-w-0 flex-col gap-2',
    item: 'flex min-w-0 items-start gap-2',
    joiner: 'mt-2 w-9 shrink-0 text-center font-mono text-[10.5px] font-semibold text-muted-foreground',
    condition: 'flex min-w-0 flex-1 flex-wrap items-center gap-2',
    fieldSelect: 'w-40',
    operatorSelect: 'w-40',
    value: 'flex min-w-0 flex-1 flex-wrap items-center gap-2',
    valueControl: 'min-w-36 flex-1',
    empty: 'text-[12.5px] text-muted-foreground',
    footer: 'flex flex-wrap items-center gap-2',
    preview: 'rounded-md border border-border bg-secondary/40 px-3 py-2 font-mono text-[12px] text-foreground',
  },
  variants: {
    depth: {
      0: { group: 'bg-card' },
      1: { group: 'bg-secondary/30' },
      2: { group: 'bg-secondary/50' },
    },
  },
  defaultVariants: { depth: 0 },
});

export type QueryBuilderVariantProps = VariantProps<typeof queryBuilderVariants>;

/**
 * QueryBuilder model: a serialisable tree of AND/OR groups and field conditions, plus pure
 * helpers to describe it (`queryToString`) and to test a record against it (`evaluateQuery`).
 */
import { interpolate } from '../../i18n/format';
import { catalogs } from '../../i18n/messages';
import { en, type MessageKey, type Messages } from '../../i18n/messages/en';

export type QueryFieldType = 'text' | 'number' | 'enum' | 'date' | 'boolean';

export type QueryOperator =
  | 'eq'
  | 'neq'
  | 'contains'
  | 'notContains'
  | 'startsWith'
  | 'endsWith'
  | 'gt'
  | 'gte'
  | 'lt'
  | 'lte'
  | 'between'
  | 'in'
  | 'notIn'
  | 'before'
  | 'after'
  | 'isEmpty'
  | 'isNotEmpty'
  | 'isTrue'
  | 'isFalse';

export interface QueryFieldOption {
  value: string;
  label: string;
}

export interface QueryField {
  id: string;
  label: string;
  type: QueryFieldType;
  /** Choices of an `enum` field. */
  options?: QueryFieldOption[];
  /** Restricts the operators offered (defaults to every operator of the type). */
  operators?: QueryOperator[];
}

/**
 * A condition's value: text, number, boolean, an option list (`in` / `notIn`), a `[from, to]`
 * pair (`between`) or null. Dates are `YYYY-MM-DD` strings.
 */
export type QueryValue = string | number | boolean | string[] | [number | null, number | null] | [string, string] | null;

export interface QueryCondition {
  type: 'condition';
  id: string;
  /** A `QueryField.id`. */
  field: string;
  operator: QueryOperator;
  value?: QueryValue;
}

export interface QueryGroup {
  type: 'group';
  id: string;
  combinator: 'and' | 'or';
  children: QueryNode[];
}

export type QueryNode = QueryCondition | QueryGroup;

/** Operators per field type, in menu order. */
export const QUERY_OPERATORS: Record<QueryFieldType, QueryOperator[]> = {
  text: ['eq', 'neq', 'contains', 'notContains', 'startsWith', 'endsWith', 'isEmpty', 'isNotEmpty'],
  number: ['eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'between', 'isEmpty', 'isNotEmpty'],
  enum: ['eq', 'neq', 'in', 'notIn', 'isEmpty', 'isNotEmpty'],
  date: ['eq', 'before', 'after', 'between', 'isEmpty', 'isNotEmpty'],
  boolean: ['isTrue', 'isFalse'],
};

export const operatorsFor = (field: QueryField | undefined): QueryOperator[] => (field ? (field.operators ?? QUERY_OPERATORS[field.type]) : []);

/** How many values an operator takes: none, one, a `[from, to]` pair, or a list. */
export function operatorArity(op: QueryOperator): 'none' | 'one' | 'pair' | 'list' {
  if (op === 'isEmpty' || op === 'isNotEmpty' || op === 'isTrue' || op === 'isFalse') return 'none';
  if (op === 'between') return 'pair';
  if (op === 'in' || op === 'notIn') return 'list';
  return 'one';
}

/** A fresh node id (call it from event handlers, not during render). */
export const newQueryId = () => `q${Math.random().toString(36).slice(2, 10)}`;

export function createQueryGroup(combinator: 'and' | 'or' = 'and', children: QueryNode[] = []): QueryGroup {
  return { type: 'group', id: newQueryId(), combinator, children };
}

export function createQueryCondition(field: QueryField | undefined): QueryCondition {
  return { type: 'condition', id: newQueryId(), field: field?.id ?? '', operator: operatorsFor(field)[0] ?? 'eq' };
}

/** True when a condition has the values its operator needs. */
export function isConditionComplete(c: QueryCondition): boolean {
  const arity = operatorArity(c.operator);
  if (!c.field) return false;
  if (arity === 'none') return true;
  const v = c.value;
  if (arity === 'pair') return Array.isArray(v) && v.length === 2 && v.every((x) => x !== '' && x !== null && x !== undefined);
  if (arity === 'list') return Array.isArray(v) && v.length > 0;
  return v !== undefined && v !== null && v !== '';
}

// ------------------------------------------------------------------ queryToString

export interface QueryToStringOptions {
  /** Field definitions: labels for fields and enum options. Without them, ids are shown. */
  fields?: QueryField[];
  /** Picks the built-in catalog for operator words ("en" default). */
  locale?: string;
  /** Translator (e.g. `useI18n().t`); overrides `locale`. */
  t?: (key: MessageKey, vars?: Record<string, string | number>) => string;
}

/**
 * Human-readable query: `Status is "Active" AND (Age greater than 30 OR Country is any of
 * "Spain", "France")`. Incomplete conditions and empty groups are left out.
 */
export function queryToString(tree: QueryNode, options: QueryToStringOptions = {}): string {
  const lang = (options.locale ?? 'en').split(/[-_]/)[0]?.toLowerCase() ?? 'en';
  const messages: Messages = (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
  const t = options.t ?? ((key: MessageKey, vars?: Record<string, string | number>) => interpolate(messages[key] ?? en[key], vars, options.locale ?? 'en'));
  const fieldOf = (id: string) => options.fields?.find((f) => f.id === id);

  const literal = (field: QueryField | undefined, v: unknown): string => {
    if (typeof v === 'number') return String(v);
    if (typeof v === 'boolean') return t(v ? 'queryBuilder.true' : 'queryBuilder.false');
    const s = String(v);
    const label = field?.options?.find((o) => o.value === s)?.label ?? s;
    return field?.type === 'date' ? label : `"${label}"`;
  };

  const visit = (node: QueryNode, nested: boolean): string => {
    if (node.type === 'condition') {
      if (!isConditionComplete(node)) return '';
      const field = fieldOf(node.field);
      const head = `${field?.label ?? node.field} ${t(`queryBuilder.op.${node.operator}`)}`;
      const arity = operatorArity(node.operator);
      const v = node.value;
      if (arity === 'none') return head;
      if (arity === 'pair' && Array.isArray(v)) return `${head} ${t('queryBuilder.between', { from: literal(field, v[0]), to: literal(field, v[1]) })}`;
      if (arity === 'list' && Array.isArray(v)) return `${head} ${(v as unknown[]).map((x) => literal(field, x)).join(', ')}`;
      return `${head} ${literal(field, v)}`;
    }
    const parts = node.children.map((c) => visit(c, true)).filter(Boolean);
    const joined = parts.join(` ${t(node.combinator === 'and' ? 'queryBuilder.and' : 'queryBuilder.or')} `);
    return nested && parts.length > 1 ? `(${joined})` : joined;
  };
  return visit(tree, false);
}

// ------------------------------------------------------------------ evaluateQuery

const DAY = /^\d{4}-\d{2}-\d{2}/;
const pad = (n: number) => String(n).padStart(2, '0');

/** `YYYY-MM-DD` of a Date (local) or of a date/datetime string; null otherwise. */
function dayKey(v: unknown): string | null {
  if (v instanceof Date) return Number.isNaN(v.getTime()) ? null : `${v.getFullYear()}-${pad(v.getMonth() + 1)}-${pad(v.getDate())}`;
  if (typeof v === 'string' && DAY.test(v)) return v.slice(0, 10);
  return null;
}

const isEmptyValue = (v: unknown) => v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
const norm = (v: unknown) => String(v ?? '').toLowerCase();

function compare(a: unknown, b: unknown, type: QueryFieldType | undefined): number | null {
  if (type === 'date' || (type === undefined && dayKey(b) !== null && dayKey(a) !== null)) {
    const x = dayKey(a);
    const y = dayKey(b);
    return x === null || y === null ? null : x < y ? -1 : x > y ? 1 : 0;
  }
  const x = typeof a === 'number' ? a : Number(a);
  const y = typeof b === 'number' ? b : Number(b);
  if (a === null || a === undefined || a === '' || Number.isNaN(x) || Number.isNaN(y)) return null;
  return x - y;
}

function equals(a: unknown, b: unknown, type: QueryFieldType | undefined): boolean {
  if (Array.isArray(a)) return a.some((x) => equals(x, b, type));
  if (type === 'number' || typeof b === 'number') return compare(a, b, 'number') === 0;
  if (type === 'date') return compare(a, b, 'date') === 0;
  if (type === 'enum') return String(a) === String(b);
  return norm(a) === norm(b);
}

function test(c: QueryCondition, record: Record<string, unknown>, type: QueryFieldType | undefined): boolean {
  const v = record[c.field];
  const target = c.value;
  switch (c.operator) {
    case 'isEmpty':
      return isEmptyValue(v);
    case 'isNotEmpty':
      return !isEmptyValue(v);
    case 'isTrue':
      return v === true;
    case 'isFalse':
      return v === false;
    case 'eq':
      return equals(v, target, type);
    case 'neq':
      return !equals(v, target, type);
    case 'contains':
      return norm(v).includes(norm(target));
    case 'notContains':
      return !norm(v).includes(norm(target));
    case 'startsWith':
      return norm(v).startsWith(norm(target));
    case 'endsWith':
      return norm(v).endsWith(norm(target));
    case 'in':
    case 'notIn': {
      const list = Array.isArray(target) ? (target as unknown[]).map(String) : [];
      const hit = Array.isArray(v) ? v.some((x) => list.includes(String(x))) : list.includes(String(v));
      return c.operator === 'in' ? hit : !hit;
    }
    case 'between': {
      if (!Array.isArray(target)) return false;
      const lo = compare(v, target[0], type);
      const hi = compare(v, target[1], type);
      return lo !== null && hi !== null && lo >= 0 && hi <= 0;
    }
    default: {
      const d = compare(v, target, c.operator === 'before' || c.operator === 'after' ? 'date' : type);
      if (d === null) return false;
      if (c.operator === 'gt' || c.operator === 'after') return d > 0;
      if (c.operator === 'gte') return d >= 0;
      if (c.operator === 'lt' || c.operator === 'before') return d < 0;
      return d <= 0;
    }
  }
}

const hasCompleteCondition = (node: QueryNode): boolean =>
  node.type === 'condition' ? isConditionComplete(node) : node.children.some(hasCompleteCondition);

/**
 * Whether `record` matches the query. Text comparisons ignore case; dates compare by day
 * (`YYYY-MM-DD` strings or Date objects); array-valued record fields match `eq` / `in` when any
 * item does. Incomplete conditions are ignored, and an empty group matches everything.
 * Pass `fields` so values are compared by their declared type.
 */
export function evaluateQuery(tree: QueryNode, record: Record<string, unknown>, fields?: QueryField[]): boolean {
  if (tree.type === 'condition') {
    if (!isConditionComplete(tree)) return true;
    return test(tree, record, fields?.find((f) => f.id === tree.field)?.type);
  }
  const relevant = tree.children.filter(hasCompleteCondition);
  if (!relevant.length) return true;
  return tree.combinator === 'and' ? relevant.every((c) => evaluateQuery(c, record, fields)) : relevant.some((c) => evaluateQuery(c, record, fields));
}

import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({ locale, messages, dir, applyTo = 'wrapper', children }: I18nProviderProps) {
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, ...createFormatters(locale, merged) };
  }, [locale, messages, direction]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages): I18nFormatters {
  function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now = unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatCurrency: (value, currency, options) => new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate: (value, options = { dateStyle: 'medium' }) => new Intl.DateTimeFormat(locale, options).format(toDate(value)),
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) => new Intl.ListFormat(locale, options).format(items),
  };
}

import { en, type Messages } from './en';
import { es } from './es';

/** Built-in catalogs, by language subtag. */
export const catalogs = { en, es } satisfies Record<string, Messages>;
export type CatalogLocale = keyof typeof catalogs;
